/* The sitemap lists exactly the pages the site serves.
 *
 * It was hand-kept and had fallen to 19 of 40 pages. It is generated by
 * build.py now; this holds the generated file to the folder it describes, in
 * both directions, so a page added outside the build or a listing left behind
 * after a page is removed both fail here.
 *
 * Run from the repository root:  node source/test/sitemap-verify.mjs
 */
import { readFileSync, readdirSync, existsSync } from "node:fs";

let pass = 0, fail = 0;
const is = (c, t) => { if (c) { pass++; console.log("  ok   " + t); }
                       else { fail++; console.log("  FAIL " + t); } };
const BASE = "https://aseemm84.github.io/Astro/";
const xml = readFileSync("sitemap.xml", "utf8");
const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
const listed = locs.map((u) => u.slice(BASE.length));
const pages = readdirSync(".").filter((f) => f.endsWith(".html") && f !== "404.html").sort();

console.log("The sitemap and the site");
is(locs.every((u) => u.startsWith(BASE)), `every URL is under ${BASE}`);
is(new Set(listed).size === listed.length, `no page listed twice (${listed.length} listed)`);
const missing = pages.filter((p) => !listed.includes(p));
is(missing.length === 0, `every served page is listed (${pages.length})` + (missing.length ? " — missing: " + missing.join(", ") : ""));
const ghost = listed.filter((p) => !existsSync(p));
is(ghost.length === 0, "every listed page exists" + (ghost.length ? " — not found: " + ghost.join(", ") : ""));
is(!listed.includes("404.html") && !listed.some((p) => p.includes("/")), "no 404 page and nothing from test/");
is(/^Sitemap:\s*https:\/\/aseemm84\.github\.io\/Astro\/sitemap\.xml\s*$/m.test(readFileSync("robots.txt", "utf8")),
   "robots.txt points at it");
is(/<urlset xmlns="http:\/\/www\.sitemaps\.org\/schemas\/sitemap\/0\.9">/.test(xml) && xml.trim().endsWith("</urlset>"),
   "it is a well-formed sitemap document");
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
